1	package agentusageview
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	
9		"github.com/charmbracelet/lipgloss"
10	
11		"github.com/anthnel/devdesk/internal/agentusage"
12		"github.com/anthnel/devdesk/internal/agentusage/pricing"
13		"github.com/anthnel/devdesk/internal/ui/datatable"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	const (
18		// noValue is the dash of a cell with nothing to show.
19		noValue = "-"
20		// noModel stands for an agent whose transcript named no model.
21		noModel = noValue
22		// unknownID stands for a sub-agent whose ID is empty, so it cannot be
23		// mistaken for the orchestrator, which has no short ID by design.
24		unknownID = "?"
25		// unknownType stands for a sub-agent whose meta file gave no type.
26		unknownType = "unknown"
27		// orchestratorLabel is the Agent cell of the main agent.
28		orchestratorLabel = "orchestrator"
29		// partialMark prefixes an output count that is a floor, not an exact value.
30		partialMark = "≥ "
31		// stem and lastStem draw the tree branch in front of a sub-agent's type.
32		stem     = "├─ "
33		lastStem = "└─ "
34	)
35	
36	// agentIDPrefix is the shortest agent ID shown.
37	const agentIDPrefix = 8
38	
39	// agentRow is one line of the agents table.
40	type agentRow struct {
41		agentusage.Agent
42		branch  string   // stem, lastStem, or "" (orchestrator, or a sorted list)
43		shortID string   // ID prefix, distinct within the session; "" for the orchestrator
44		share   int      // tenths of a percent of the session total, or noShare
45		key     string   // identity across rebuilds, see agentKeys
46		state   runState // what the State column shows
47		cost    pricing.Estimate
48	}
49	
50	// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
51	// gives each its short ID and share, and draws the branches when tree is true.
52	// The sort is stable so equal IDs keep their input order.
53	func agentRows(u agentusage.Usage, tree bool, c statusClock, prices pricing.Table) []agentRow {
54		var main, subs []agentusage.Agent
55		for _, a := range u.Agents {
56			if a.Main {
57				main = append(main, a)
58			} else {
59				subs = append(subs, a)
60			}
61		}
62		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
63	
64		ordered := append(append([]agentusage.Agent{}, main...), subs...)
65		totals := make([]int64, len(ordered))
66		for i, a := range ordered {
67			totals[i] = a.Tokens.Total()
68		}
69		mainIdx := -1
70		if len(main) > 0 {
71			mainIdx = 0
72		}
73		parts := shares(totals, u.Total().Total(), mainIdx)
74	
75		ids := make([]string, len(subs))
76		for i, a := range subs {
77			ids[i] = a.ID
78		}
79		short := shortAgentIDs(ids)
80	
81		keys := agentKeys(ordered)
82		states := agentStates(ordered, c)
83		rows := make([]agentRow, 0, len(ordered))
84		for i, a := range ordered {
85			row := agentRow{Agent: a, share: parts[i], key: keys[i], state: states[i], cost: prices.Agent(a)}
86			if !a.Main {
87				j := i - len(main)
88				row.shortID = short[j]
89				if tree {
90					row.branch = stem
91					if j == len(subs)-1 {
92						row.branch = lastStem
93					}
94				}
95			}
96			rows = append(rows, row)
97		}
98		return rows
99	}
100	
101	// shortAgentIDs cuts every ID to one common length, the smallest n >=
102	// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
103	// own length.
104	func shortAgentIDs(ids []string) []string {
105		if len(ids) == 0 {
106			return nil
107		}
108		longest := 0
109		runes := make([][]rune, len(ids))
110		for i, id := range ids {
111			runes[i] = []rune(id)
112			longest = max(longest, len(runes[i]))
113		}
114		cut := func(n int) []string {
115			out := make([]string, len(runes))
116			for i, r := range runes {
117				out[i] = string(r[:min(n, len(r))])
118			}
119			return out
120		}
121		for n := agentIDPrefix; n < longest; n++ {
122			seen := make(map[string]bool, len(ids))
123			distinct := true
124			for _, s := range cut(n) {
125				if seen[s] {
126					distinct = false
127					break
128				}
129				seen[s] = true
130			}
131			if distinct {
132				return cut(n)
133			}
134		}
135		return cut(longest)
136	}
137	
138	// agentColumns describes the agents table. Only Total sorts, largest first;
139	// without a sort the order is the tree. Columns give way on a narrow terminal
140	// in this order: Cache write, Est. cost, Cache read, In, Model, Duration, Tools, State
141	// (Cache write and Est. cost are DropFirst, the rightmost first). Est. cost is visible
142	// from about 126 columns (it depends on the content of the Agent and ID columns). The ID never gives way, so two agents of one type stay apart.
143	func agentColumns() []datatable.Column[agentRow] {
144		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
145			return datatable.Column[agentRow]{
146				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
147				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
148				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
149			}
150		}
151		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
152		in.Optional = true
153		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
154		cacheRead.Optional = true
155		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
156		cacheWrite.Optional, cacheWrite.DropFirst = true, true
157		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
158		total.Less = func(a, b agentRow) bool { return a.Tokens.Total() < b.Tokens.Total() }
159		total.DescFirst = true
160	
161		out := count("Out", 7, nil)
162		out.Cell = outCell
163		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
164	
165		return []datatable.Column[agentRow]{
166			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
167				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
168			{Title: "ID", Sizing: datatable.SizingContent, MinWidth: agentIDPrefix, Cell: idCell,
169				Search: func(r agentRow) string { return r.ID },
170				Style:  func(r agentRow) lipgloss.Style { return dimWhen(idCell(r) == noValue || idCell(r) == unknownID) }},
171			costColumn(), stateColumn(), toolsColumn(), durationColumn(),
172			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Optional: true, Cell: modelsCell, Search: modelsCell,
173				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
174			in, out, cacheRead, cacheWrite, total,
175			{Title: "Share", Sizing: datatable.SizingFixed, MinWidth: len("100.0%"), Cell: shareCell,
176				Style: func(r agentRow) lipgloss.Style { return dimWhen(r.share <= 0) }},
177		}
178	}
179	
180	// stateColumn is the State column: the label is searchable, so `/idle` keeps
181	// the idle agents. Idle is the one state that reads as a warning.
182	func stateColumn() datatable.Column[agentRow] {
183		label := func(r agentRow) string { return r.state.label() }
184		return datatable.Column[agentRow]{
185			Title: "State", Sizing: datatable.SizingFixed, MinWidth: len("running"), Optional: true,
186			Cell: label, Search: label,
187			Style: func(r agentRow) lipgloss.Style {
188				switch r.state {
189				case stateIdle:
190					return theme.SeverityTextStyle("MEDIUM")
191				case stateUnknown:
192					return theme.DimStyle
193				}
194				return lipgloss.NewStyle()
195			},
196		}
197	}
198	
199	// toolsColumn is the Tools column: distinct tool calls read from the transcript.
200	func toolsColumn() datatable.Column[agentRow] {
201		return datatable.Column[agentRow]{
202			Title: "Tools", Sizing: datatable.SizingFixed, MinWidth: 5, Optional: true,
203			Cell:  func(r agentRow) string { return formatTokens(int64(r.ToolCalls)) },
204			Style: func(r agentRow) lipgloss.Style { return dimWhen(r.ToolCalls == 0) },
205		}
206	}
207	
208	// durationColumn is the Duration column: first to last line of the transcript.
209	func durationColumn() datatable.Column[agentRow] {
210		cell := func(r agentRow) string { return formatDuration(r.Duration(), !r.FirstActivity.IsZero()) }
211		return datatable.Column[agentRow]{
212			Title: "Duration", Sizing: datatable.SizingFixed, MinWidth: len("Duration"), Optional: true,
213			Cell:  cell,
214			Style: func(r agentRow) lipgloss.Style { c := cell(r); return dimWhen(c == noValue || c == "0s") },
215		}
216	}
217	
218	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
219	// anything else keeps the default colour.
220	func dimWhen(dim bool) lipgloss.Style {
221		if dim {
222			return theme.DimStyle
223		}
224		return lipgloss.NewStyle()
225	}
226	
227	// agentSearch is what `/` matches in the Agent column: the role. The full ID is
228	// searched through the ID column.
229	func agentSearch(r agentRow) string { return roleCell(r) }
230	
231	// idCell is the ID column: the short ID of a sub-agent, a dash for the
232	// orchestrator, which has none.
233	func idCell(r agentRow) string {
234		switch {
235		case r.Main:
236			return noValue
237		case r.shortID == "":
238			return unknownID
239		}
240		return r.shortID
241	}
242	
243	// shareCell is the Share column.
244	func shareCell(r agentRow) string { return formatShare(r.share) }
245	
246	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
247	// its branch.
248	func roleCell(r agentRow) string {
249		if r.Main {
250			return orchestratorLabel
251		}
252		typ := r.Type
253		if typ == "" {
254			typ = unknownType
255		}
256		return r.branch + typ
257	}
258	
259	// modelsCell lists the models the agent used.
260	func modelsCell(r agentRow) string {
261		if len(r.Models) == 0 {
262			return noModel
263		}
264		return strings.Join(r.Models, ", ")
265	}
266	
267	// outCell is the output count. A sub-agent still being written is a floor and
268	// says so; the orchestrator never does, its transcript is the one being read.
269	func outCell(r agentRow) string {
270		out := formatTokens(r.Tokens.Output)
271		if !r.Main && r.PartialOutput() {
272			return partialMark + out
273		}
274		return out
275	}
276	
277	// formatTokens renders a count compactly, floored to one decimal: 1099 is
278	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
279	func formatTokens(n int64) string {
280		units := []struct {
281			size   int64
282			suffix string
283		}{
284			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
285		}
286		for _, u := range units {
287			if n < u.size {
288				continue
289			}
290			tenths := n / (u.size / 10) // divide first: n*10 would overflow
291			if tenths >= 1000 {
292				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
293			}
294			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
295		}
296		return fmt.Sprintf("%d", n)
297	}
298	
299	// formatDuration renders a duration compactly; known is false when the
300	// transcript carried no timestamp.
301	func formatDuration(d time.Duration, known bool) string {
302		if !known {
303			return noValue
304		}
305		switch {
306		case d < time.Minute:
307			return fmt.Sprintf("%ds", max(int(d/time.Second), 0))
308		case d < time.Hour:
309			return fmt.Sprintf("%dm%02ds", int(d/time.Minute), int(d%time.Minute/time.Second))
310		case d < 24*time.Hour:
311			return fmt.Sprintf("%dh%02dm", int(d/time.Hour), int(d%time.Hour/time.Minute))
312		case d < 100*24*time.Hour:
313			return fmt.Sprintf("%dd%02dh", int(d/(24*time.Hour)), int(d%(24*time.Hour)/time.Hour))
314		}
315		return ">99d"
316	}
