package agentusageview

import (
	"fmt"
	"math/bits"
)

const (
	// shareScale is a share's precision: tenths of a percent.
	shareScale = 1000
	// noShare marks a share that cannot be computed: the session has no tokens.
	noShare = -1
)

// shares returns each total's part of the session total in tenths of a
// percent, floored. The entry at mainIdx takes the rounding residue so the
// parts add up to shareScale; mainIdx < 0 leaves every part floored. A zero
// total yields noShare everywhere.
func shares(totals []int64, total int64, mainIdx int) []int {
	out := make([]int, len(totals))
	if total <= 0 {
		for i := range out {
			out[i] = noShare
		}
		return out
	}
	rest := shareScale
	for i, t := range totals {
		out[i] = floorTenths(t, total)
		if i != mainIdx {
			rest -= out[i]
		}
	}
	if mainIdx >= 0 && mainIdx < len(out) {
		out[mainIdx] = max(rest, 0) // clamped: saturated totals can overshoot
	}
	return out
}

// floorTenths is floor(part*shareScale/total) on 128 bits, so no product
// overflows. part is clamped to [0, total]; total > 0.
func floorTenths(part, total int64) int {
	part = min(max(part, 0), total)
	hi, lo := bits.Mul64(uint64(part), shareScale)
	q, _ := bits.Div64(hi, lo, uint64(total)) // hi < total because part <= total
	return int(q)
}

// formatShare renders tenths of a percent: 123 is "12.3%"; noShare is "-".
func formatShare(tenths int) string {
	if tenths < 0 {
		return noValue
	}
	return fmt.Sprintf("%d.%d%%", tenths/10, tenths%10)
}

package agentusageview

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// The reasons, written once so the header, the footer and the tests cannot
// drift apart on the wording (Rule 129 — English US).
const (
	reasonNoSession     = "No session to open"
	reasonInsideSession = "Already inside a session"
	reasonTopLevel      = "Already at the session list"
)

// actions is what the keys allow right now, computed once and read by both
// halves of the view: GetShortcuts to grey out, the handlers to refuse
// (Rule 130).
type actions struct {
	Open  shortcut.Availability // → and enter
	Close shortcut.Availability // ← and esc
}

// availability computes the answers from the level and the selected row.
func (m Model) availability() actions {
	var a actions
	if m.level == levelAgents {
		a.Open = shortcut.Unavailable(reasonInsideSession)
		return a
	}
	a.Close = shortcut.Unavailable(reasonTopLevel)
	if _, ok := m.table.Selected(); !ok {
		a.Open = shortcut.Unavailable(reasonNoSession)
	}
	return a
}

// guard runs act when the action is available, and otherwise refuses with the
// reason as a Warn: nothing failed, the action does not apply (Rule 128).
func (m Model) guard(a shortcut.Availability, act func() (tea.Model, tea.Cmd)) (tea.Model, tea.Cmd) {
	if !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	return act()
}

package agentusageview

import (
	"fmt"
	"slices"
	"strings"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// mainKey is the key of the orchestrator, of which a session has one.
const mainKey = "main"

// agentKeys names agents so the same one keeps its key from one rebuild to the
// next: "main" for the orchestrator, "sub:<ID>#n" for a sub-agent, n counting
// the earlier agents that share its ID (an ID is not guaranteed unique). It
// must be given the canonical order (agentRows), never the sorted or filtered
// one: under a sort, two twins would trade keys whenever they trade ranks.
func agentKeys(agents []agentusage.Agent) []string {
	seen := make(map[string]int, len(agents))
	keys := make([]string, len(agents))
	for i, a := range agents {
		if a.Main {
			keys[i] = mainKey
			continue
		}
		keys[i] = fmt.Sprintf("sub:%s#%d", a.ID, seen[a.ID])
		seen[a.ID]++
	}
	return keys
}

// populationOf lists what makes a table "another population" for the column
// widths: which agents it holds, and the models each one names. Counts change
// on every delta and do not count. A type can change too (its meta arrives
// after the transcript) but stays out on purpose: the column is remeasured at
// the next ctrl+r or change of population.
func populationOf(rows []agentRow) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.key + "|" + strings.Join(r.Models, ",")
	}
	return out
}

// withUsage shows u in the agents table, keeping the cursor on the agent it was
// on (whatever the filter and the sort do to the order), and clears the
// loading and error states. The columns are remeasured only on a full read or
// when the population changed, so a two-second delta never reshuffles them.
func (m Model) withUsage(u agentusage.Usage, full bool) Model {
	m = m.withRows(u, full)
	m.agentsLoading, m.agentsErr = false, false
	return m
}

// withRows rebuilds the agents table from u without touching the loading and
// error states, so a red footer survives the rebuild.
func (m Model) withRows(u agentusage.Usage, full bool) Model {
	before := populationOf(m.agentTable.Items())
	selected, hadSelection := m.selectedAgentKey()
	cursor := m.agentTable.Cursor()

	rows := agentRows(u, m.agentsTree(), m.clock, m.prices)
	m.usage = u
	m.cost = m.prices.Session(u)
	m.agentTable.SetItems(rows)

	if full || !slices.Equal(before, populationOf(rows)) {
		m.agentTable.Remeasure()
	}
	m.agentTable.SetCursor(cursor) // clamps when the agent vanished
	if hadSelection {
		m.selectAgentKey(selected)
	}
	return m
}

// selectAgentKey moves the cursor onto the visible row with that key, if any.
func (m *Model) selectAgentKey(key string) {
	if i := slices.IndexFunc(m.agentTable.Visible(), func(r agentRow) bool { return r.key == key }); i >= 0 {
		m.agentTable.SetCursor(i)
	}
}

// selectedAgentKey is the key of the row under the cursor.
func (m Model) selectedAgentKey() (string, bool) {
	r, ok := m.agentTable.Selected()
	return r.key, ok
}

package agentusage

import "time"

// Agent is the usage of one agent of a session: the orchestrator (Main) or a
// sub-agent.
type Agent struct {
	ID              string
	Main            bool
	Type            string // sub-agent type from its meta file; "" if unknown
	Models          []string
	Tokens          Tokens
	ByModel         []ModelUsage // per-model split of Tokens; the "" bucket (no model, or past maxModelsPerAgent) last
	Messages        int          // distinct message ids
	PartialMessages int          // messages whose last line has no stop reason
	State           State
	SpawnDepth      int
	ToolCalls       int       // distinct tool_use blocks of the agent's assistant lines
	FirstActivity   time.Time // earliest line timestamp (UTC); zero if none
	LastActivity    time.Time // latest line timestamp (UTC); zero if none
	// key is the table's identity for the agent's lines (the rank of its
	// transcript); empty means ID. finish clears it from its output.
	key string
}

// ModelUsage is the part of an agent's tokens billed to one model, with the
// share of its cache writes that used the 1 h cache. Summed over an agent's
// ByModel it equals Agent.Tokens.
type ModelUsage struct {
	Model        string // "" for messages that name no model, and for models past maxModelsPerAgent
	Tokens       Tokens
	CacheWrite1h int64 // of Tokens.CacheWrite, written with the 1 h cache
}

// CacheWrite5m is the cache writes that used the 5 min cache.
func (m ModelUsage) CacheWrite5m() int64 { return m.Tokens.CacheWrite - m.CacheWrite1h }

// Duration is LastActivity - FirstActivity, or 0 unless both are known.
func (a Agent) Duration() time.Duration {
	if a.FirstActivity.IsZero() || a.LastActivity.IsZero() {
		return 0
	}
	return a.LastActivity.Sub(a.FirstActivity)
}

// PartialOutput reports whether some message of the agent was still being
// written (no stop reason on its last line), so its output count is a floor.
func (a Agent) PartialOutput() bool { return a.PartialMessages > 0 }

// IssueKind classifies a line that could not be counted.
type IssueKind int

const (
	IssueUnreadable IssueKind = iota // not JSON, truncated, or bad counters
	IssueOversized                   // longer than MaxLineBytes
	IssueOpenFailed                  // a sub-agent transcript could not be opened
	IssueReadError                   // reading stopped on an I/O error at Offset
)

// FileIssue locates one skipped line. File is a base name, never a path.
type FileIssue struct {
	File   string
	Offset int64
	Kind   IssueKind
}

// Diagnostics counts what parsing skipped or had to guess.
type Diagnostics struct {
	UnreadableLines     int
	OversizedLines      int
	NoUsage             int
	NoMessageID         int
	CrossFileDuplicates int
	MetaMissing         int
	MetaUnreadable      int
	TruncatedFiles      []string
	Files               []FileIssue
}

// Degraded reports whether anything was skipped or guessed.
func (d Diagnostics) Degraded() bool {
	return d.UnreadableLines > 0 || d.OversizedLines > 0 || d.NoUsage > 0 ||
		d.NoMessageID > 0 || d.CrossFileDuplicates > 0 || d.MetaMissing > 0 ||
		d.MetaUnreadable > 0 || len(d.TruncatedFiles) > 0 || len(d.Files) > 0
}

// Usage is the parsed usage of one session.
type Usage struct {
	SessionID   string
	Agents      []Agent
	Versions    []string
	Diagnostics Diagnostics
	Billed      Billed
}

// Billed is the session cost Claude Code recorded itself, in the last
// cost-state line of the parent transcript.
type Billed struct {
	USD float64 // 0 unless Known
	// Known is false while the session runs (no cost-state yet), when any line
	// follows the last cost-state (the session was resumed), or when that line
	// is invalid or names another session.
	Known bool
}

// Total returns the tokens of every agent.
func (u Usage) Total() Tokens {
	var t Tokens
	for _, a := range u.Agents {
		t = t.Add(a.Tokens)
	}
	return t
}

