277	// formatTokens renders a count compactly, floored to one decimal: 1099 is
278	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
279	func formatTokens(n int64) string {
280		units := []struct {
281			size   int64
282			suffix string
283		}{
284			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
285		}
286		for _, u := range units {
287			if n < u.size {
288				continue
289			}
290			tenths := n / (u.size / 10) // divide first: n*10 would overflow
291			if tenths >= 1000 {
292				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
293			}
294			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
295		}
296		return fmt.Sprintf("%d", n)
297	}
298	
299	// formatDuration renders a duration compactly; known is false when the
300	// transcript carried no timestamp.
301	func formatDuration(d time.Duration, known bool) string {
302		if !known {
303			return noValue
304		}
305		switch {
306		case d < time.Minute:
307			return fmt.Sprintf("%ds", max(int(d/time.Second), 0))
308		case d < time.Hour:
309			return fmt.Sprintf("%dm%02ds", int(d/time.Minute), int(d%time.Minute/time.Second))
310		case d < 24*time.Hour:
311			return fmt.Sprintf("%dh%02dm", int(d/time.Hour), int(d%time.Hour/time.Minute))
312		case d < 100*24*time.Hour:
313			return fmt.Sprintf("%dd%02dh", int(d/(24*time.Hour)), int(d%(24*time.Hour)/time.Hour))
314		}
315		return ">99d"
316	}
