65	// agentsHeaderInfo counts the agents on screen and their tokens, both following
66	// the filter.
67	func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
68		rows := m.agentTable.Visible()
69		var total int64
70		estimates := make([]pricing.Estimate, len(rows))
71		for i, r := range rows {
72			total += r.Tokens.Total()
73			estimates[i] = r.cost
74		}
75		info := []shortcut.HeaderInfo{
76			{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
77			{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
78			{Key: "Est. cost", Value: estCostValue(pricing.Sum(estimates)), Style: theme.HeaderValueStyle},
79		}
80		info = append(info, m.billedHeaderInfo()...)
81		info = append(info, shortcut.HeaderInfo{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle})
82		if n := m.idleCount(); n > 0 {
83			info = append(info, shortcut.HeaderInfo{Key: "Idle", Value: strconv.Itoa(n), Style: theme.HeaderValueStyle})
84		}
85		return info
86	}
