88	// negativeUSD is half a cent: an Unattributed amount at or below its negative
89	// shows as -$0.01 or lower, so only then is the price table "above the bill".
90	// Float noise (-1e-12) renders $0.00 and must not look stale.
91	const negativeUSD = 0.005
92	
93	// billedHeaderInfo is Billed and Unattributed, both facts of the whole session
94	// that ignore the filter. Neither shows while Claude Code has not recorded a
95	// bill. Unattributed is a dash when an agent has no price, and a negative one
96	// (the price table is above what was billed) is orange.
97	func (m Model) billedHeaderInfo() []shortcut.HeaderInfo {
98		if !m.cost.Billed.Known {
99			return nil
100		}
101		unattributed := shortcut.HeaderInfo{Key: "Unattributed", Value: noValue, Style: theme.HeaderValueStyle}
102		if m.cost.UnattributedKnown {
103			unattributed.Value = formatUSD(m.cost.Unattributed)
104			if m.cost.Unattributed <= -negativeUSD {
105				unattributed.Style = theme.HeaderWarnValueStyle()
106			}
107		}
108		return []shortcut.HeaderInfo{
109			{Key: "Billed", Value: formatUSD(m.cost.Billed.USD), Style: theme.HeaderValueStyle},
110			unattributed,
111		}
112	}
