202		switch {
203		case m.loadErr:
204			return sharedcomponents.Status{
205				Text:  "Failed to list Claude Code sessions — check logs",
206				Level: sharedcomponents.LevelError,
207			}
208		case m.loading:
209			return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
210		case len(m.table.Items()) == 0:
211			return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
212		}
