220			return sharedcomponents.Status{
221				Text:  "Failed to read this session — check logs",
222				Level: sharedcomponents.LevelError,
223			}
224		case m.agentsLoading:
225			return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
226		case m.usage.Diagnostics.Degraded():
227			return sharedcomponents.Status{
228				Text:  "Totals are approximate — some transcript data could not be read",
229				Level: sharedcomponents.LevelWarning,
230			}
231		}
232		return m.priceHint()
