235	// priceHint is the footer state about missing prices: where to set them when
236	// the table is empty, which model lacks one otherwise. It is a state derived on
237	// every frame, not a message (Rule 128).
238	func (m Model) priceHint() sharedcomponents.Status {
239		if m.prices.Len() == 0 {
240			if m.usage.Total().Total() == 0 {
241				return sharedcomponents.Status{}
242			}
243			return sharedcomponents.Status{Text: "Set agent_usage.prices in this context's config file to estimate costs — see ?"}
244		}
245		switch n := len(m.cost.Unpriced); n {
246		case 0:
247			return sharedcomponents.Status{}
248		case 1:
249			return sharedcomponents.Status{Text: "No price for " + m.cost.Unpriced[0] + " in agent_usage.prices — its cost shows -"}
250		default:
251			return sharedcomponents.Status{Text: fmt.Sprintf(
252				"No price for %s and %d more models in agent_usage.prices — their cost shows -", m.cost.Unpriced[0], n-1)}
253		}
254	}
