1	package agentusageview
2	
3	import (
4		"errors"
5		"log"
6		"os"
7	
8		"github.com/charmbracelet/bubbles/spinner"
9		tea "github.com/charmbracelet/bubbletea"
10	
11		"github.com/anthnel/devdesk/internal/agentusage"
12		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// Update handles messages.
17	func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
18		switch msg := msg.(type) {
19		case tea.WindowSizeMsg:
20			return m.handleResize(msg)
21		case sessionListLoadedMsg:
22			return m.handleListLoaded(msg)
23		case usageDeltaMsg:
24			return m.handleUsageDelta(msg)
25		case usagePollTickMsg:
26			return m.handlePollTick(msg)
27		case agentsResumeMsg:
28			return m.handleResume()
29		case spinner.TickMsg:
30			return m.handleSpinnerTick(msg)
31		case tea.KeyMsg:
32			return m.handleKey(msg)
33		}
34		m.footer.Handle(msg)
35		return m, nil
36	}
37	
38	// handleResize sizes both tables, so going back from the agents level finds the
39	// sessions table already fitted. The full viewport width, borders included
40	// (Rule 116).
41	func (m Model) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
42		m.width, m.height = msg.Width, max(msg.Height-1, 1)
43		m.table.Resize(m.width, m.height)
44		m.agentTable.Resize(m.width, m.height)
45		return m, nil
46	}
47	
48	// handleListLoaded takes a listing, or ignores one from a superseded read.
49	// A failed read keeps the rows already shown: they are dated, not wrong.
50	func (m Model) handleListLoaded(msg sessionListLoadedMsg) (tea.Model, tea.Cmd) {
51		if msg.gen != m.gen {
52			return m, nil
53		}
54		m.loading = false
55		if msg.err != nil {
56			// The error can name a path; it is logged, never shown (Rule 128).
57			log.Printf("ERROR [agentusageview] list sessions: %v", msg.err)
58			m.loadErr = true
59			return m, nil
60		}
61		m.loadErr = false
62		m.root = msg.root
63		m.omitted = msg.listing.Omitted
64		m.table.SetItems(rowsOf(msg))
65		return m, nil
66	}
67	
68	// rowsOf folds each project once, so no Cell does it per frame.
69	func rowsOf(msg sessionListLoadedMsg) []sessionRow {
70		rows := make([]sessionRow, len(msg.listing.Sessions))
71		for i, s := range msg.listing.Sessions {
72			project := noProject
73			if s.Project != "" {
74				project = theme.FoldHome(s.Project)
75			}
76			rows[i] = sessionRow{Session: s, project: project}
77		}
78		return rows
79	}
80	
81	// handleSpinnerTick advances the spinner only while a read or a parse is in
82	// flight, so the chain ends with the load.
83	func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
84		if !m.loading && !m.agentsLoading {
85			return m, nil
86		}
87		var cmd tea.Cmd
88		m.spinner, cmd = m.spinner.Update(msg)
89		m.footer.SetSpinnerFrame(m.spinner.View())
90		return m, cmd
91	}
92	
93	// handleUsageDelta takes the answer to the read in flight, or drops one that
94	// is for another generation or that nobody is waiting for. A failed read keeps
95	// the rows already shown.
96	func (m Model) handleUsageDelta(msg usageDeltaMsg) (tea.Model, tea.Cmd) {
97		if msg.gen != m.agentGen || m.level != levelAgents || !m.reading || m.agg == nil {
98			return m, nil
99		}
100		m.reading = false
101		if msg.err != nil {
102			return m.failRead(msg)
103		}
104		if err := m.agg.Apply(msg.delta); err != nil {
105			// Not read from the current cursor: read again from where it is now.
106			log.Printf("ERROR [agentusageview] apply delta: %v", err)
107			m.reading = true
108			return m, readDeltaCmd(m.agentGen, m.agg.Cursor())
109		}
110		return m.applyRead(msg)
111	}
112	
113	// applyRead shows what a successful read brought and decides what comes next.
114	// The rows are rebuilt on every read, even an empty one: an agent turns idle
115	// precisely because nothing arrives, so the clock must move with each answer.
116	// Whether the session is settled is computed once, for the states and for the
117	// decision to stop polling.
118	func (m Model) applyRead(msg usageDeltaMsg) (tea.Model, tea.Cmd) {
119		m.agentsErr = false
120		// While a ctrl+r full read is pending, the session is shown as alive even if
121		// the delta just applied would settle it: that state is transient and
122		// intended. The full read about to start decides, and a header that flipped
123		// to paused for one frame and back would read as a glitch.
124		settled := !m.fullPending && m.agg.Activity().Settled(msg.at, quietPeriod)
125		m.clock = statusClock{now: msg.at, alive: !settled}
126		u := m.usage
127		if msg.delta.Full() || !msg.delta.Empty() {
128			u = m.agg.Usage()
129		}
130		m = m.withUsage(u, msg.delta.Full())
131		if m.fullPending {
132			m.fullPending = false
133			return m, m.startRead(true)
134		}
135		if settled {
136			m.pollStopped = true
137			return m, nil // nothing left to wait for: the chain ends here
138		}
139		return m, pollTickCmd(m.agentGen)
140	}
141	
142	// failRead records a failed read. Only the first failure of a streak is
143	// logged. The error names files by base name only; it never reaches the UI.
144	// A deleted transcript ends the poll chain; any other failure retries, after
145	// the full read a ctrl+r left pending, if there is one.
146	func (m Model) failRead(msg usageDeltaMsg) (tea.Model, tea.Cmd) {
147		if !m.agentsErr {
148			log.Printf("ERROR [agentusageview] read session: %v", msg.err)
149		}
150		m.agentsErr = true
151		if errors.Is(msg.err, os.ErrNotExist) {
152			m.agentsLoading, m.fullPending, m.pollStopped = false, false, true
153			m.clock = statusClock{now: msg.at}
154			return m.withRows(m.usage, false), nil
155		}
156		if m.fullPending {
157			m.fullPending = false
158			return m, m.startRead(true)
159		}
160		m.agentsLoading = false
161		return m, pollTickCmd(m.agentGen)
162	}
163	
164	// handlePollTick starts the incremental read a tick asks for, unless the tick
165	// belongs to a superseded chain or a read is already in flight. No spinner:
166	// polling is silent.
167	func (m Model) handlePollTick(msg usagePollTickMsg) (tea.Model, tea.Cmd) {
168		if msg.gen != m.agentGen || m.level != levelAgents || m.agg == nil || m.reading || m.pollStopped {
169			return m, nil
170		}
171		return m, m.startRead(false)
172	}
173	
174	// Leave stops the open session's chain when the router switches away: the new
175	// generation drops any tick or read still in flight, and nothing is awaited
176	// any more. The session stays open and coming back resumes it (handleResume).
177	// A pending ctrl+r is kept, and so is a full read lost in flight (a ctrl+r, or
178	// the open's first read): the resume repeats it as a full read. It never refuses.
179	func (m Model) Leave() (tea.Model, tea.Cmd, bool) {
180		if m.level == levelAgents {
181			m.agentGen++
182			m.fullPending = m.fullPending || (m.reading && m.agentsLoading)
183			m.reading, m.agentsLoading = false, false
184		}
185		return m, nil, true
186	}
187	
188	// handleResume restarts the open session's chain under a new generation, which
189	// drops the answers of any earlier chain. It reads from the cursor, silently;
190	// a ctrl+r left pending by Leave becomes a full read, with its spinner.
191	func (m Model) handleResume() (tea.Model, tea.Cmd) {
192		if m.level != levelAgents || m.agg == nil {
193			return m, nil
194		}
195		m.agentGen++
196		m.pollStopped = false
197		if m.fullPending {
198			m.fullPending = false
199			return m, tea.Batch(m.startRead(true), m.spinner.Tick)
200		}
201		return m, m.startRead(false)
202	}
203	
204	// startRead marks a read in flight and returns it; full reads everything again.
205	func (m *Model) startRead(full bool) tea.Cmd {
206		c := m.agg.Cursor()
207		if full {
208			c = c.Rewound()
209			m.agentsLoading, m.fullPending, m.pollStopped = true, false, false
210		}
211		m.reading = true
212		return readDeltaCmd(m.agentGen, c)
213	}
214	
215	// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
216	// screen, → and enter open a session, ← and esc go back.
217	func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
218		if m.InEditMode() {
219			return m, m.activeTable(msg)
220		}
221		key := msg.String()
222		if key == "ctrl+r" {
223			return m.refresh()
224		}
225		a := m.availability()
226		switch key {
227		case "right", "enter":
228			return m.guard(a.Open, m.openSelected)
229		case "left", "esc":
230			// Silent at the top level: a stray esc is not worth a footer line.
231			if a.Close.Enabled() {
232				return m.closeAgents()
233			}
234		case ".":
235			if m.level == levelAgents {
236				return m.cycleAgentSort(msg)
237			}
238		}
239		return m, m.activeTable(msg)
240	}
241	
242	// agentsTree reports whether the agents table shows the tree: no sort active.
243	func (m Model) agentsTree() bool {
244		column, _ := m.agentTable.SortState()
245		return column < 0
246	}
247	
248	// cycleAgentSort hands `.` to the agents table, then rebuilds the rows so the
249	// branches follow the new order: a sorted list is flat, a branch there would
250	// lie about who is whose child.
251	func (m Model) cycleAgentSort(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
252		selected, hadSelection := m.selectedAgentKey()
253		cmd := m.agentTable.Update(msg)
254		m.agentTable.SetItems(agentRows(m.usage, m.agentsTree(), m.clock, m.prices))
255		m.agentTable.Remeasure() // the Agent column narrows or widens by the branch
256		if hadSelection {
257			m.selectAgentKey(selected)
258		}
259		return m, cmd
260	}
261	
262	// activeTable hands a key to the table of the level on screen.
263	func (m *Model) activeTable(msg tea.KeyMsg) tea.Cmd {
264		if m.level == levelAgents {
265			return m.agentTable.Update(msg)
266		}
267		return m.table.Update(msg)
268	}
269	
270	// openSelected opens the selected session's agents. The table stays empty,
271	// headers included, until the parse answers (Rule 139).
272	func (m Model) openSelected() (tea.Model, tea.Cmd) {
273		row, _ := m.table.Selected() // availability checked a row exists
274		m.usage, m.clock = agentusage.Usage{}, statusClock{}
275		m.level = levelAgents
276		m.open = row.Session
277		m.agentGen++
278		m.agg = agentusage.NewAggregate(row.Parent)
279		m.fullPending, m.agentsErr = false, false
280		m.agentTable.FilterBar().ClearSearch() // a filter typed for another session
281		m.agentTable.SetItems(nil)
282		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
283	}
284	
285	// closeAgents returns to the sessions, cursor and filter as they were. Bumping
286	// agentGen drops a parse still in flight.
287	func (m Model) closeAgents() (tea.Model, tea.Cmd) {
288		m.level = levelSessions
289		m.agentGen++
290		m.agentsLoading, m.agentsErr = false, false
291		m.agg, m.reading, m.fullPending = nil, false, false
292		m.usage, m.clock = agentusage.Usage{}, statusClock{}
293		m.agentTable.SetItems(nil)
294		return m, nil
295	}
296	
297	// refresh starts a new read of the level on screen under a new generation.
298	// The rows stay on screen.
299	func (m Model) refresh() (tea.Model, tea.Cmd) {
300		if m.level == levelAgents {
301			return m.refreshAgents()
302		}
303		m.gen++
304		m.loading = true
305		m.loadErr = false
306		return m, tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
307	}
308	
309	// refreshAgents reads the open session from the start. A read already in
310	// flight is never doubled (one per Aggregate): the full read follows its answer.
311	func (m Model) refreshAgents() (tea.Model, tea.Cmd) {
312		if m.agg == nil {
313			m.agg = agentusage.NewAggregate(m.open.Parent)
314		}
315		if m.reading {
316			spin := !m.agentsLoading // a spinner chain already runs otherwise
317			m.fullPending, m.agentsLoading = true, true
318			if spin {
319				return m, m.spinner.Tick
320			}
321			return m, nil
322		}
323		m.agentGen++
324		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
325	}
326	
327	// InEditMode tells the router the filter has the keyboard.
328	func (m Model) InEditMode() bool { return m.activeFilterBar().InEditMode() }
329	
330	// FilterBarVisible closes the viewport rectangle around the bar.
331	func (m Model) FilterBarVisible() bool { return m.activeFilterBar().IsVisible() }
332	
333	// activeFilterBar is the bar of the level on screen; each level has its own.
334	func (m Model) activeFilterBar() *sharedcomponents.FilterBar {
335		if m.level == levelAgents {
336			return m.agentTable.FilterBar()
337		}
338		return m.table.FilterBar()
339	}
340

1	package agentusageview
2	
3	import (
4		"fmt"
5		"math/bits"
6	)
7	
8	const (
9		// shareScale is a share's precision: tenths of a percent.
10		shareScale = 1000
11		// noShare marks a share that cannot be computed: the session has no tokens.
12		noShare = -1
13	)
14	
15	// shares returns each total's part of the session total in tenths of a
16	// percent, floored. The entry at mainIdx takes the rounding residue so the
17	// parts add up to shareScale; mainIdx < 0 leaves every part floored. A zero
18	// total yields noShare everywhere.
19	func shares(totals []int64, total int64, mainIdx int) []int {
20		out := make([]int, len(totals))
21		if total <= 0 {
22			for i := range out {
23				out[i] = noShare
24			}
25			return out
26		}
27		rest := shareScale
28		for i, t := range totals {
29			out[i] = floorTenths(t, total)
30			if i != mainIdx {
31				rest -= out[i]
32			}
33		}
34		if mainIdx >= 0 && mainIdx < len(out) {
35			out[mainIdx] = max(rest, 0) // clamped: saturated totals can overshoot
36		}
37		return out
38	}
39	
40	// floorTenths is floor(part*shareScale/total) on 128 bits, so no product
41	// overflows. part is clamped to [0, total]; total > 0.
42	func floorTenths(part, total int64) int {
43		part = min(max(part, 0), total)
44		hi, lo := bits.Mul64(uint64(part), shareScale)
45		q, _ := bits.Div64(hi, lo, uint64(total)) // hi < total because part <= total
46		return int(q)
47	}
48	
49	// formatShare renders tenths of a percent: 123 is "12.3%"; noShare is "-".
50	func formatShare(tenths int) string {
51		if tenths < 0 {
52			return noValue
53		}
54		return fmt.Sprintf("%d.%d%%", tenths/10, tenths%10)
55	}
56

1	// Package agentusage reads coding-agent usage logs. It is pure stdlib and
2	// has no dependency on the UI.
3	package agentusage
4	
5	import "math"
6	
7	// Tokens counts the tokens of one or more agent requests.
8	type Tokens struct {
9		Input      int64
10		Output     int64
11		CacheRead  int64
12		CacheWrite int64
13	}
14	
15	// Total returns the sum of the four counters, saturating at math.MaxInt64.
16	func (t Tokens) Total() int64 {
17		return satAdd(satAdd(t.Input, t.Output), satAdd(t.CacheRead, t.CacheWrite))
18	}
19	
20	// Add returns the field-wise sum of t and o, each field saturating at
21	// math.MaxInt64.
22	func (t Tokens) Add(o Tokens) Tokens {
23		return Tokens{
24			Input:      satAdd(t.Input, o.Input),
25			Output:     satAdd(t.Output, o.Output),
26			CacheRead:  satAdd(t.CacheRead, o.CacheRead),
27			CacheWrite: satAdd(t.CacheWrite, o.CacheWrite),
28		}
29	}
30	
31	// satAdd adds two non-negative counters without wrapping.
32	func satAdd(a, b int64) int64 {
33		if a > math.MaxInt64-b {
34			return math.MaxInt64
35		}
36		return a + b
37	}
