// Package keymap declares the application's keyboard vocabulary.
//
// It does not read any key and does not depend on bubbletea: it is a list of
// strings, and its only role is to be the reference the tests check the code
// against (keymap_test.go). Without this reference, key consistency is a
// convention that nothing verifies — which is exactly the state §3.26 found:
// 184 bindings, 16 collisions.
//
// # Three disjoint namespaces
//
//   - An UPPERCASE letter is an action, and its meaning is global to the
//     application. `D` deletes, in every view, whatever "delete" means
//     wherever you are.
//   - A lowercase letter is a filter or a display toggle. It changes
//     nothing, so its meaning can be local and two views can use the same
//     letter without contradicting each other.
//   - Everything else (arrows, esc, enter, tab, space, `/`, `.`, `?`, `:`) is
//     structural and never changes.
//
// # Why Shift carries the actions
//
// This isn't a matter of taste, it's the real budget of a terminal:
//
//	Ctrl+letter  : only encodes ASCII 0x40-0x5F, and the tty confiscates
//	               four of them (ctrl+i = TAB, ctrl+m = Enter, ctrl+j = LF,
//	               ctrl+h = Backspace). ctrl+a and ctrl+b are screen's and
//	               tmux's prefixes, ctrl+c/ctrl+d are SIGINT and EOF,
//	               ctrl+s/ctrl+q are flow control.           → ~14 left
//	Alt+key      : Option is not Meta on macOS unless the user enables it;
//	               the application receives nothing.                → 0
//	Ctrl+Shift   : the control code erases case — ctrl+a and ctrl+shift+a
//	               both emit 0x01. Telling them apart requires the Kitty
//	               keyboard protocol or modifyOtherKeys, which bubbletea
//	               v1.3.10 does not enable (that's WithKeyboardEnhancements()
//	               in v2). And even then the emulator claims them first:
//	               ctrl+shift+c/v/t/w/n are copy, paste, tab, close, window.
//	                                                                  → 0
//	Shift+letter : no constraint. Works on every emulator, every platform,
//	               through SSH and tmux.                             → 26
//
// Shift+letter IS a two-key combination: two fingers, no accidental firing.
// It carries the vocabulary not by default, but because the two other
// families are crippled or unusable.
package keymap

import (
	"maps"
	"sort"
	"strings"
)

// The 24 actions. About forty actions used to exist for 26 letters: the
// rule only holds after merging synonyms (Kill = stop and kill,
// Delete = delete and remove, Terminal = terminal and shell) and because
// display toggles are excluded from the count.
const (
	New      = "N" // Create a resource from this context
	Edit     = "E" // Edit the selected resource
	Delete   = "D" // Delete the selected resource
	Rename   = "M" // Rename (mv)
	Scan     = "S" // Scan the selected target
	ScanAll  = "A" // Scan everything (modal: "purge the cache first" checkbox)
	Fetch    = "F" // Catch up with the source: fetch + fast-forward, or follow a stream
	Clone    = "C" // Enter clone selection
	Terminal = "T" // Open a terminal or shell
	IDE      = "O" // Open in the configured IDE
	Web      = "W" // Open a URL in the browser
	Logs     = "L" // Open the logs
	Pager    = "V" // Open in the system pager
	Kill     = "K" // Stop, kill (modal: Stop / Restart, or SIGKILL)
	Prune    = "P" // Remove unused resources
	Browser  = "B" // Open the multi-registry browser
	Get      = "G" // Pull (get) the image or tag
	Auth     = "U" // Login / logout of the registry — toggles based on the row's state
	Exclude  = "X" // Exclude — add to .gitleaksignore
	Requests = "R" // Open merge requests · PRs
	Issues   = "I" // Open issues
	Diagnose = "H" // Open network diagnostics on this target
	// Jump took J from the free letters: it opens the selected row's related
	// resource in the view that owns it — the image a container runs, today.
	Jump = "J" // Jump to the related resource in its own view
	// Copy is `Y` — yank. The letter was free even though a modal uses it
	// for "Yes": a modal claims every key before the view sees it, so the
	// two are never reachable at the same time.
	Copy = "Y" // Copy the obvious thing to the clipboard — a path, a document's content, the MCP connect command
)

// CommandMode opens the command palette, from anywhere — including from a
// focused text field.
//
// ctrl+p, and not ctrl+: : ":" is 0x3A, outside the 0x40-0x5F range Ctrl
// encodes, so "ctrl+:" never reaches the application. The fallback was
// alt+:, which has the opposite flaw: on Terminal.app and iTerm2,
// Option+Shift+; emits a literal character and the key doesn't arrive
// either. ctrl+p is free throughout the application, is not a tty control
// character, is not the prefix of any multiplexer, and its meaning is
// already learned — command palette.
const CommandMode = "ctrl+p"

// actions maps each action key to its meaning. This is the table the tests
// check the code against; the table in §3.26 is its readable form.
var actions = map[string]string{
	New:      "Create a resource from this context",
	Edit:     "Edit the selected resource",
	Delete:   "Delete the selected resource",
	Rename:   "Rename",
	Scan:     "Scan the selected target",
	ScanAll:  "Scan everything",
	Fetch:    "Catch up with the source",
	Clone:    "Enter clone selection",
	Terminal: "Open a terminal or shell",
	IDE:      "Open in the configured IDE",
	Web:      "Open a URL in the browser",
	Logs:     "Open the logs",
	Pager:    "Open in the system pager",
	Kill:     "Stop or kill",
	Prune:    "Remove unused resources",
	Browser:  "Open the multi-registry browser",
	Get:      "Pull the image or tag",
	Auth:     "Log in or out of the registry",
	Exclude:  "Exclude — add to .gitleaksignore",
	Requests: "Open merge requests · PRs",
	Issues:   "Open issues",
	Diagnose: "Open network diagnostics on this target",
	Jump:     "Jump to the related resource in its own view",
	Copy:     "Copy the obvious thing to the clipboard",
}

// Actions returns a copy of the key → meaning table.
func Actions() map[string]string {
	out := make(map[string]string, len(actions))
	maps.Copy(out, actions)
	return out
}

// IsAction reports whether a key belongs to the action vocabulary.
func IsAction(key string) bool {
	_, ok := actions[key]
	return ok
}

// modalKeys are the shortcuts of a confirmation modal.
//
// This is a fourth namespace, and it is disjoint from the other three by
// mode rather than by case: a modal claims every key before the view sees
// it (priority 1 in every handleKeyMsg), so `N` cannot mean "create" there
// — the view underneath receives nothing. Same argument as for InEditMode.
//
// They are declared here because the §3.26 survey had not seen them, and
// an uppercase letter bound without a declaration is indistinguishable
// from drift.
var modalKeys = map[string]string{
	"y": "Yes", "Y": "Yes",
	"n": "No", "N": "No",
}

// ModalKeys returns the modal shortcuts.
func ModalKeys() map[string]string {
	out := make(map[string]string, len(modalKeys))
	maps.Copy(out, modalKeys)
	return out
}

// IsModalKey reports whether a key is a modal shortcut.
func IsModalKey(key string) bool {
	_, ok := modalKeys[key]
	return ok
}

// free lists the uppercase letters no action occupies. They are declared
// rather than left to be inferred: the next addition must know where to
// pick from without redoing the survey, and an action that settles
// somewhere other than here is a duplicate that goes unnoticed.
// H came back here with §3.47 (it used to trace the route, removed because
// it answered for the Docker VM rather than for the machine, D57) and left
// again with Diagnose (§3.66): a good semantic fit for "look closer at this
// target's network path." A letter an action has just freed up is
// re-declared free, otherwise it stays reserved for a use that no longer
// exists. J left with Jump (a container's image, opened in the OCI view).
var free = []string{"Q", "Z"}

// Free returns the still-available uppercase letters, sorted.
func Free() []string {
	out := append([]string(nil), free...)
	sort.Strings(out)
	return out
}

// Surface is a screen, its files, and the lowercase letters it uses.
//
// Path is what ties a file to its surface, and it is there so the
// declaration is checkable: without it, "these letters are local to this
// view" is verified by merging every list, and `l` declared for netdiag
// would excuse `l` in the registries. Matching is done on the longest
// prefix, so netdiag/ports can narrow down netdiag.
type Surface struct {
	Name string
	Path string
	Keys []string
}

// localToggles inventories the lowercase letters used as display or filter
// toggles. They change nothing, so their meaning is local and the same
// letter can serve twice without contradiction — `l` is the protocol in
// netdiag and the LOW severity in security.
//
// A file that matches no surface is entitled to no lowercase letter at
// all: that is the default, and it is what makes the list worth keeping
// up to date.
var localToggles = []Surface{
	{"containers", "ui/containers/", []string{"r", "p", "s", "t", "z"}},
	{"viewer", "ui/viewer/", []string{"f", "c", "w", "v", "t", "n", "g", "s"}},
	{"netdiag/ports", "ui/netdiag/ports_model.go", []string{"t", "u", "l", "e", "n", "z"}},
	{"netdiag/checks", "ui/netdiag/", []string{"p"}},
	{"oci/browser", "ui/oci_resources/browser_", []string{"r"}},
	{"security/findings", "ui/security/", []string{"c", "h", "m", "l"}},
	// g opens the fuzzy-find prompt across the whole workspaces tree. Same
	// justification as the viewer's g: the jump takes an argument (the typed
	// query), which is not a role home/end/G could ever cover.
	{"workspaces", "ui/workspaces/", []string{"g"}},
	// The same prompt over the forge index: every namespace and repository
	// the session can see, at any depth.
	{"forge/explorer", "ui/forge/explorer/", []string{"g"}},
}

// LocalToggles returns the declared surfaces.
func LocalToggles() []Surface {
	return append([]Surface(nil), localToggles...)
}

// SurfaceFor ties a file path to its surface, by longest prefix. The
// second return says whether a surface was found.
func SurfaceFor(path string) (Surface, bool) {
	var best Surface
	found := false
	for _, s := range localToggles {
		if !strings.Contains(path, s.Path) {
			continue
		}
		if !found || len(s.Path) > len(best.Path) {
			best, found = s, true
		}
	}
	return best, found
}

// Exception is a key that deviates from the vocabulary, with its reason.
type Exception struct {
	Key     string
	Surface string
	Why     string
}

// exceptions are the accepted deviations. They are written here
// because §3.26 requires it: an undeclared exception is indistinguishable
// from drift, and the next survey would "fix" it.
var exceptions = []Exception{
	{
		Key:     "o",
		Surface: "security/results/ci-tab",
		Why: "Ouvrir le pipeline résolu par le forge. Même raison que `c` : " +
			"l'action n'existe que sur un onglet, et brûler une des trois " +
			"dernières majuscules libres pour ça coûterait plus que ça ne " +
			"rapporte. `o` plutôt qu'une autre lettre parce qu'il veut déjà " +
			"dire « ouvrir ce que cet écran désigne » dans l'état détail de " +
			"la même vue, où il ouvre la référence d'un finding.",
	},
	{
		Key:     "ctrl+y",
		Surface: "oci/launch-form",
		Why: "Copier la commande docker run. Même raison, et ctrl+y ne heurte " +
			"aucun caractère de contrôle utilisé ailleurs.",
	},
	{
		Key:     "ctrl+o",
		Surface: "security/results/remediation-tab",
		Why: "Write the chosen base images into the Dockerfiles. The action " +
			"exists on one tab, so a global capital would cost more than it " +
			"returns. ^O is Write Out in nano; bubbletea puts the terminal in " +
			"raw mode, which switches off the only other job ^O has in a tty " +
			"(discard output). The obvious alternatives are taken: ctrl+w closes " +
			"a browser or web-terminal tab, ctrl+s is flow control, and ctrl+d is " +
			"end-of-file.",
	},
	{
		Key:     "tab",
		Surface: "app/command-line",
		Why: "Complete the highlighted suggestion. The command palette has no tabs " +
			"and no fields, so tab's usual jobs (Rule 135: switch tabs, never " +
			"move between fields) do not exist there, and completing is what " +
			"tab means in every shell. Nothing is run: enter does that.",
	},
}

// DeclaredExceptions returns the declared exceptions.
func DeclaredExceptions() []Exception {
	return append([]Exception(nil), exceptions...)
}

// IsException reports whether a key is a declared exception on a surface.
func IsException(key string) bool {
	for _, e := range exceptions {
		if e.Key == key {
			return true
		}
	}
	return false
}

package theme

import (
	"math"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/config"
)

// A load gauge: a bar that answers "is something hot" without reading a
// number (§3.71).
//
// By default every cell is the same glyph — `░` — used or not. What used to
// tell a filled cell from an empty one by shape then does it by colour alone:
// LoadTextStyle on the fill, GaugeTrackStyle on the track, split by
// datatable.Column.Cut after the text is already measured (Rule 122). A value
// survives the row disappearing under the cursor only through the number
// beside the gauge — Style is not consulted on the selected row, and with one
// glyph the bar itself has nothing left to say once its colour is gone.
//
// `app.gauge_glyph: block` opts into a solid `█` fill over the `░` track,
// which keeps that shape under the cursor. It is an opt-in because `█` is
// East Asian ambiguous width (see gaugeGlyph): the user, not the locale,
// knows how their terminal draws it.

// gaugeGlyph is the glyph of the track, and of the fill by default. `░` is a
// Block Elements glyph, and the *only* one of the family that measures 1 cell
// in both the default and the East Asian `runewidth` condition — every other
// glyph in the range (`█`, `▓`, `▇`, the partial blocks `▏▎▍▌`) is *ambiguous*
// and renders double-width on some terminals, which would overflow the
// column and break Rule 116. Measured, not assumed.
const gaugeGlyph = "░"

// gaugeBlockGlyph is the fill the "block" gauge style swaps in. Ambiguous
// width, hence never the default: a terminal that draws it double-width
// overflows every gauge column, and only the user can know that.
const gaugeBlockGlyph = "█"

// gaugeFillGlyph is the glyph the filled cells render, set once from
// app.gauge_glyph by SetGaugeGlyph. Process-wide state like the palette
// ApplyTheme writes: it is only touched from Update() and read while
// rendering, both on the Bubble Tea loop.
var gaugeFillGlyph = gaugeGlyph

// SetGaugeGlyph selects the fill glyph from an app.gauge_glyph value. Anything
// but "block" — including a typo in the file — is the safe `░`.
func SetGaugeGlyph(style string) {
	if style == config.GaugeGlyphBlock {
		gaugeFillGlyph = gaugeBlockGlyph
		return
	}
	gaugeFillGlyph = gaugeGlyph
}

// GaugeWidth is the width of a gauge column, in cells.
//
// Ten: with a single glyph carrying no shape of its own, resolution is one
// cell per `GaugeWidth`th of the scale — 10% here — and a wider bar reads
// better than a narrower one at the same resolution the old half-braille
// design gave for six. The number beside it still carries the exact value.
const GaugeWidth = 10

// Load thresholds, in percent: green, then orange, then red — the colour a
// *filled* cell takes; GaugeTrackStyle below is what an *empty* one always
// takes, whatever the level.
const (
	// LoadWarnPercent is where a gauge stops being ordinary: filling up, and
	// worth noticing.
	LoadWarnPercent = 75
	// LoadCriticalPercent is where it is nearly full — the memory gauge's
	// reading of a container about to meet its limit.
	LoadCriticalPercent = 90
)

// Gauge renders a bar of width cells at pct, as plain text: GaugeFillWidth
// fill glyphs, then track glyphs. In the default style the two are the same
// character and the value lives entirely in how many cells a caller colours
// with LoadTextStyle rather than GaugeTrackStyle (datatable.Column.Cut, after
// measurement — never inside this string); with "block" the text carries the
// split too.
func Gauge(pct float64, width int) string {
	return GaugeFill(GaugeFillWidth(pct, width)) + GaugeTrack(width-GaugeFillWidth(pct, width))
}

// GaugeFill renders n filled cells, for a caller that styles the two runs
// itself (a waterfall bar).
func GaugeFill(n int) string {
	if n <= 0 {
		return ""
	}
	return strings.Repeat(gaugeFillGlyph, n)
}

// GaugeTrack renders n empty cells. Always `░`, whatever the fill is.
func GaugeTrack(n int) string {
	if n <= 0 {
		return ""
	}
	return strings.Repeat(gaugeGlyph, n)
}

// GaugeFillWidth reports how many of Gauge's width cells count as filled —
// the boundary datatable.Column.Cut needs to hand LoadTextStyle the first
// cells and GaugeTrackStyle the rest.
//
// pct is clamped: anything at or above 100 fills the bar. Saturation is
// therefore indistinguishable from exactly full, which is deliberate and is
// the reason a gauge never replaces the number beside it — `docker stats`
// counts CPU against one core, so two busy cores read 200% and only the
// number tells the two apart (§3.71).
//
// Rounding is honest at the low end too: a container at 0.1% fills zero
// cells rather than one. A tenth of the bar *is* 10%, so lighting one for a
// value near zero would overstate it on every idle row — and idle is what
// most rows are.
func GaugeFillWidth(pct float64, width int) int {
	if width <= 0 {
		return 0
	}
	switch {
	case math.IsNaN(pct), pct < 0:
		pct = 0
	case pct > 100:
		pct = 100
	}
	return int(math.Round(pct / 100 * float64(width)))
}

// LoadTextStyle is the colour a gauge's *filled* cells take at pct: green,
// then orange, then red. It follows SeverityTextStyle's shape — the view
// names a value, the theme answers with a colour — and it aliases the
// severity palette for the same reason the footer levels do (Rule 128): one
// alphabet across the application, so a full gauge reads like a CRITICAL
// finding.
//
// It is a function rather than a package-level style because the thresholds
// are the whole of it; a var per level would leave the switch in the view,
// which is where Rule 125 says a colour must not be decided.
func LoadTextStyle(pct float64) lipgloss.Style {
	base := lipgloss.NewStyle().Background(ColorBackground)
	switch {
	case pct >= LoadCriticalPercent:
		return base.Foreground(ColorSeverityCritical).Bold(true)
	case pct >= LoadWarnPercent:
		return base.Foreground(ColorSeverityMedium)
	default:
		return base.Foreground(ColorOK)
	}
}

// TimingBarWidth is the width of a waterfall bar (§3.66), in cells — wider
// than GaugeWidth: a waterfall has several phases to tell apart on one line,
// where a gauge answers a single percentage, and the extra resolution is what
// keeps a phase as small as a handful of percent visible at all.
const TimingBarWidth = 24

// TimingFillStyle is the colour a waterfall bar's filled cells take (§3.66) —
// reusing Gauge/GaugeFillWidth for the glyph and the rounding, but not
// LoadTextStyle for the colour: a phase taking most of a request's time is
// not a problem to spot, just a fact to read, so it gets one neutral colour
// rather than a severity gradient. ColorSecondary is what headers and active
// tabs already use for structural information, which is the same role here.
func TimingFillStyle() lipgloss.Style {
	return lipgloss.NewStyle().Background(ColorBackground).Foreground(ColorSecondary)
}

// GaugeTrackStyle is the colour a gauge's *empty* cells take — fixed,
// whatever the level, including a gauge that is entirely empty: the cell is
// still `░`, still coloured, never blank. It aliases ColorSeverityLow rather
// than DimStyle directly: DimStyle is this application's word for *absent*
// (a `-`, a zero, a placeholder), and an empty gauge cell is not absent — it
// is measured and low. ColorSeverityLow's own default now happens to be the
// same tone as ColorDim (a LOW finding reads as unremarkable as a "0" count,
// see colors.go) — the two coincide in colour without coinciding in name, so
// a theme separating "low severity" from "nothing found" moves the track
// with the former rather than the latter.
func GaugeTrackStyle() lipgloss.Style {
	return lipgloss.NewStyle().Background(ColorBackground).Foreground(ColorSeverityLow)
}

