	left := borderStyle.Render(border.TopLeft + border.Top + " ")
	renderedTitle := titleStyle.Render(title)
	right := borderStyle.Render(" ")

	// "┌─ " = 3 chars, title, " " = 1 char, "┐" = 1 char
