		}
		if r < paletteBorderContrast {
			t.Errorf("theme %s: palette border %.2f:1 (%s on %s), want >= %.1f:1",
				name, r, ColorPaletteBorder, ColorBackground, paletteBorderContrast)
		}
	})
}

