package main
import ("encoding/json";"fmt";"math";"os";"path/filepath";"strconv")
func rgb(h string)(float64,float64,float64){ if len(h)!=7{return 0,0,0}; r,_:=strconv.ParseUint(h[1:3],16,8); g,_:=strconv.ParseUint(h[3:5],16,8); b,_:=strconv.ParseUint(h[5:7],16,8); return float64(r)/255,float64(g)/255,float64(b)/255}
func lin(c float64)float64{ if c<=0.04045{return c/12.92}; return math.Pow((c+0.055)/1.055,2.4)}
func lum(h string)float64{r,g,b:=rgb(h);return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b)}
func cr(a,b string)float64{x,y:=lum(a),lum(b); if x<y{x,y=y,x}; return (x+0.05)/(y+0.05)}
func lab(h string)(float64,float64,float64){r,g,b:=rgb(h);r,g,b=lin(r),lin(g),lin(b)
 x:=(0.4124*r+0.3576*g+0.1805*b)/0.95047; y:=0.2126*r+0.7152*g+0.0722*b; z:=(0.0193*r+0.1192*g+0.9505*b)/1.08883
 f:=func(t float64)float64{ if t>0.008856{return math.Cbrt(t)}; return 7.787*t+16.0/116}
 return 116*f(y)-16, 500*(f(x)-f(y)), 200*(f(y)-f(z))}
func de(a,b string)float64{l1,a1,b1:=lab(a);l2,a2,b2:=lab(b);return math.Sqrt((l1-l2)*(l1-l2)+(a1-a2)*(a1-a2)+(b1-b2)*(b1-b2))}
func main(){
 files,_:=filepath.Glob(os.Args[1]+"/themes/*.json")
 sets := map[string][]string{"A prim/high/sec/border":{"color_primary","color_highlight","color_secondary","color_border"},
  "B sec/high/prim/text":{"color_secondary","color_highlight","color_primary","color_text"}}
 for name,keys:=range sets{ fmt.Println("==",name)
 for _,f:=range files{ b,_:=os.ReadFile(f); m:=map[string]string{}; json.Unmarshal(b,&m)
  bg:=m["color_background"]; sel:=m["table_line_selected"]; if sel==""{sel=m["cmd_line_bg"]}
  minDE:=999.0; minCR:=99.0; minSel:=99.0; clash:=""
  for i,k:=range keys{ c:=m[k]; minCR=math.Min(minCR,cr(c,bg)); if sel!=""{minSel=math.Min(minSel,cr(c,sel))}
   for _,s:=range []string{"severity_critical","severity_high","severity_medium","severity_low","severity_info","color_ok","color_dim"}{ if m[s]==c {clash+=k+"="+s+" "}}
   for _,k2:=range keys[i+1:]{ minDE=math.Min(minDE,de(c,m[k2]))}}
  fmt.Printf("%-22s minΔE=%5.1f minCR(bg)=%4.2f minCR(sel)=%4.2f %s\n",filepath.Base(f),minDE,minCR,minSel,clash)}}
}
EOF
