 x:=(0.4124*r+0.3576*g+0.1805*b)/0.95047; y:=0.2126*r+0.7152*g+0.0722*b; z:=(0.0193*r+0.1192*g+0.9505*b)/1.08883
 f:=func(t float64)float64{ if t>0.008856{return math.Cbrt(t)}; return 7.787*t+16.0/116}
 return 116*f(y)-16, 500*(f(x)-f(y)), 200*(f(y)-f(z))}
func de(a,b string)float64{l1,a1,b1:=lab(a);l2,a2,b2:=lab(b);return math.Sqrt((l1-l2)*(l1-l2)+(a1-a2)*(a1-a2)+(b1-b2)*(b1-b2))}
func main(){
 seg:=[]string{"#89b4fa","#cba6f7","#f9e2af","#9399b2"}; names:=[]string{"input blue","output mauve","cw yellow","cr overlay2"}
 avoid:=map[string]string{"crit":"#f38ba8","high":"#eba0ac","med":"#fab387","low":"#585b70","info":"#45475a","ok/gauge":"#a6e3a1","dim":"#585b70"}
 for i,c:=range seg{ fmt.Printf("%-12s bg=%.2f sel=%.2f", names[i], cr(c,"#1e1e2e"), cr(c,"#313244"))
  m:=999.0; mk:=""; for k,a:=range avoid{ if d:=de(c,a); d<m {m=d;mk=k}}; fmt.Printf(" nearest-avoid=%s ΔE=%.1f\n",mk,m)}
 for i:=range seg{ for j:=i+1;j<len(seg);j++{ fmt.Printf("ΔE %s/%s=%.1f\n",names[i],names[j],de(seg[i],seg[j]))}}
}
